def choose_move(observation):
    def clamp(v):
        if v < -1:
            return -1
        if v > 1:
            return 1
        return v

    def as_pos(v):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            try:
                return int(v[0]), int(v[1])
            except Exception:
                return None
        if isinstance(v, dict):
            for kx, ky in (("x", "y"), ("row", "col"), ("r", "c")):
                if kx in v and ky in v:
                    try:
                        return int(v.get(kx)), int(v.get(ky))
                    except Exception:
                        return None
        return None

    def extract_positions(obj):
        out = []
        if obj is None:
            return out
        if isinstance(obj, dict):
            p = as_pos(obj)
            if p is not None:
                out.append(p)
            for v in obj.values():
                out.extend(extract_positions(v))
        elif isinstance(obj, (list, tuple)):
            if len(obj) == 2 and not isinstance(obj[0], (list, tuple, dict)) and not isinstance(obj[1], (list, tuple, dict)):
                p = as_pos(obj)
                if p is not None:
                    out.append(p)
            else:
                for it in obj:
                    out.extend(extract_positions(it))
        return out

    def unique_positions(ps):
        seen = set()
        out = []
        for p in ps:
            if p not in seen:
                seen.add(p)
                out.append(p)
        return out

    def dist2(a, b):
        dx = a[0] - b[0]
        dy = a[1] - b[1]
        return dx * dx + dy * dy

    def get_grid():
        g = observation.get("grid")
        if g is None:
            g = observation.get("board")
        if g is None:
            g = observation.get("map")
        return g

    grid = get_grid()
    h = len(grid) if isinstance(grid, (list, tuple)) else 0
    w = len(grid[0]) if h and isinstance(grid[0], (list, tuple)) else 0

    me = None
    for k in ("position", "pos", "agent_pos", "agent_position", "self_pos", "self_position", "player_pos", "player_position"):
