                    if a.get("is_self") or a.get("self") or a.get("me"):
                        me = as_pos(a.get("position")) or as_pos(a.get("pos"))
                        if me is not None:
                            break
            if me is None:
                for a in agents:
                    if isinstance(a, dict):
                        me = as_pos(a.get("position")) or as_pos(a.get("pos"))
                        if me is not None:
                            break
                    else:
                        me = as_pos(a)
                        if me is not None:
                            break
    if me is None:
