    # Targets
    targets = []
    for key in ("resources", "resource_positions", "food", "items", "pickups", "goals", "goal_positions", "targets", "objective_positions"):
        targets.extend(extract_positions(observation.get(key)))
    if not targets:
        for key in ("territory", "capture_points", "bases", "flags", "control_points"):
            targets.extend(extract_positions(observation.get(key)))
    targets = unique_positions(targets)

    # Enemies / threats
    threats = []
    for key in ("enemies", "enemy_positions", "opponents", "opponent_positions", "pursuers", "hunter_positions"):
