    blocked = set()
    for key in ("walls", "blocked", "obstacles", "rocks", "barriers", "hazards"):
        for p in extract_positions(observation.get(key)):
            blocked.add(p)
    if isinstance(grid, (list, tuple)) and h:
        for i in range(h):
            row = grid[i]
            if isinstance(row, (list, tuple)):
                for j in range(min(len(row), w or len(row))):
                    cell = row[j]
                    if cell in (1, "#", "X", "x", "wall", "W", True):
                        blocked.add((i, j))

    # Heuristic score for each move
    best = (0, 0)
