                if dmin is None or d < dmin:
                    dmin = d
            score += 30.0 / (1.0 + dmin)

        if threats:
            for e in threats:
                d = dist2((nx, ny), e)
                score -= 40.0 / (1.0 + d)

            # extra flee if very close
            dmin_e = None
            for e in threats:
                d = dist2((nx, ny), e)
                if dmin_e is None or d < dmin_e:
                    dmin_e = d
            if dmin_e is not None and dmin_e <= 4:
                score -= 10.0 / (1.0 + dmin_e)

        # Prefer movement over waiting if something exists
        if dx == 0 and dy == 0:
            score -= 0.2

