        if not targets and not threats and h and w:
            cx, cy = (h - 1) / 2.0, (w - 1) / 2.0
            score -= 0.05 * ((nx - cx) * (nx - cx) + (ny - cy) * (ny - cy))

        if best_score is None or score > best_score:
            best_score = score
            best = (dx, dy)

    return [clamp(best[0]), clamp(best[1])]

